CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,email TEXT UNIQUE NOT NULL,password_hash TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN('attendee','admin')),created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS events(id INTEGER PRIMARY KEY AUTOINCREMENT,title TEXT NOT NULL,description TEXT NOT NULL,event_date TEXT NOT NULL,event_time TEXT NOT NULL,location TEXT NOT NULL,capacity INTEGER NOT NULL CHECK(capacity>0),status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN('draft','published','completed','cancelled')),created_by INTEGER NOT NULL REFERENCES users(id),created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS registrations(id INTEGER PRIMARY KEY AUTOINCREMENT,event_id INTEGER NOT NULL REFERENCES events(id),user_id INTEGER NOT NULL REFERENCES users(id),status TEXT NOT NULL DEFAULT 'active' CHECK(status IN('active','cancelled')),created_at TEXT DEFAULT CURRENT_TIMESTAMP,cancelled_at TEXT);
CREATE UNIQUE INDEX IF NOT EXISTS one_active_registration ON registrations(event_id,user_id) WHERE status='active';
